implementation:
#include <linux/uaccess.h>
#include <linux/sock.h>

int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen) {
    int assoc_id_size = sizeof(__u32);
    __u32 assoc_id;
    struct sctp_assoc_stats stats;

    if (len < assoc_id_size) {
        return -EINVAL;
    }

    if (copy_from_user(&assoc_id, optval, assoc_id_size)) {
        return -EFAULT;
    }

    sctp_get_assoc_stats_data(sk, assoc_id, &stats);

    stats.max_rto = max(stats.rto, stats.max_rto);

    if (copy_to_user(optval, &stats, sizeof(stats))) {
        return -EFAULT;
    }

    if (put_user(sizeof(stats), optlen)) {
        return -EFAULT;
    }

    return 0;
}
